    #[test]
    fn typed_shared_provider_projection_keeps_exact_upstream_bodies_and_metadata() {
        use sha2::{Digest, Sha256};
        for (relative, original, expected_sha) in SHARED_PROVIDER_FIXTURES {
            let projected = typed_ingress_shared_blueprint(relative, original).unwrap();
            assert!(projected.starts_with(metadata_only(original).unwrap().as_str()));
            assert_eq!(&format!("{:x}", Sha256::digest(projected.as_bytes())), expected_sha);
            if *relative == "frameworks/base/packages/SystemUI/Android.bp" {
                assert!(projected.contains("name: \"SystemUI-core\""));
            } else {
                assert!(!projected.contains("name: \"SystemUI-core\""));
            }
            assert!(!projected.contains("name: \"PlatformMotionTestingRoboApplication\""));
            assert!(!projected.contains("name: \"platform-screenshot-diff-test\""));
        }
    }

    #[test]
    fn typed_systemui_defaults_preserve_real_consumers_and_dependency_edges() {
        use sha2::{Digest, Sha256};
        let original = SHARED_PROVIDER_FIXTURES[0].1;
        let projected = typed_ingress_shared_blueprint(
            "frameworks/base/packages/SystemUI/Android.bp", original).unwrap();
        // Real same-commit consumers exposed the omission. Keep their full
        // sources fixed and retain each complete upstream provider, including
        // its flags library or Dagger annotation processor dependency.
        for (consumer, expected_sha, name, dependency) in [
            (include_str!("../../../android/native-role-ingress/provider-fixtures/SystemUI-tests.Android.bp"),
             "f1b2422c693a8f8c52034369ded585a3a93ac861f9dd6dd73f0801a77e6be4da", "systemui-non-platform-apis-defaults", "android.os.flags-aconfig-java"),
            (include_str!("../../../android/native-role-ingress/provider-fixtures/SystemUI-pods-build.Android.bp"),
             "45a406d917e55d45ad1ef0eafd27f2146a894dbcd309813e5c58b1a1b9e6400f", "SystemUI_compile_dagger", "dagger2-compiler"),
            (include_str!("../../../android/native-role-ingress/provider-fixtures/SystemUI-pods-policy.Android.bp"),
             "abdbfc9d78daa2785dd2cb953b4ec081f135df032e348fab78c2731262744533", "SystemUI_compile_dagger", "dagger2-compiler"),
        ] {
            assert_eq!(format!("{:x}", Sha256::digest(consumer.as_bytes())), expected_sha);
            assert!(consumer.contains(&format!("\"{name}\"")));
            let marker = format!("java_defaults {{\n    name: \"{name}\",");
            let start = original.find(&marker).unwrap();
            let end = start + original[start..].find("\n}\n").unwrap() + 3;
            let upstream = &original[start..end];
            assert!(upstream.contains(&format!("\"{dependency}\"")));
            assert_eq!(projected.matches(upstream).count(), 1);
        }
    }

